@Composable
fun YearBalanceCard(
    expense: Double,
    income: Double,
    modifier: Modifier = Modifier
) {
    val balance = income - expense

    Card(
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = androidx.compose.foundation.BorderStroke(1.dp, Color.Black)
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "本年结余",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = "¥ ${String.format(Locale.CHINA, "%.2f", balance)}",
                    style = MaterialTheme.typography.headlineMedium,
                    color = Color(0xFFF06292), // Pink/Red color matching the image
                    fontWeight = FontWeight.Bold
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text(text = "本年支出", color = Color.Gray, fontSize = 14.sp)
                Text(
                    text = if (expense > 0) "¥ ${String.format(Locale.CHINA, "%.2f", expense)}" else "暂无",
                    color = Color.Gray,
                    fontSize = 14.sp
                )
            }

            Spacer(modifier = Modifier.height(8.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text(text = "本年收入", color = Color.Gray, fontSize = 14.sp)
                Text(
                    text = if (income > 0) "¥ ${String.format(Locale.CHINA, "%.2f", income)}" else "暂无",
                    color = Color.Gray,
                    fontSize = 14.sp
                )
            }
        }
    }
}

