Card( modifier = modifier .fillMaxWidth() .padding(horizontal = 16.dp), shape = RoundedCornerShape(12.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceContainer), border = BorderStroke(1.dp, Color.Black) ) { Column(modifier = Modifier.padding(16.dp)) { // Top Row: Balance Label and Balance Amount Row( modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Text( text = balanceLabel, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold ) Text( text = "¥ ${String.format(Locale.CHINA, "%.2f", balanceAmount)}", style = MaterialTheme.typography.headlineMedium, color = Color(0xFFF06292), fontWeight = FontWeight.Bold ) }
