// Expense Row Row( modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically ) { Text( text = expenseLabel, color = Color.Gray, fontSize = 14.sp, modifier = Modifier.width(60.dp) ) Spacer(modifier = Modifier.width(8.dp)) Box( modifier = Modifier .weight(1f) .height(8.dp) .background(Color.Gray.copy(alpha = 0.5f), RoundedCornerShape(4.dp)) ) { Box( modifier = Modifier .fillMaxHeight() .fillMaxWidth(expFraction) .background(Color(0xFFF44336), RoundedCornerShape(4.dp)) ) } Spacer(modifier = Modifier.width(8.dp)) Text( text = if (expenseAmount > 0) "¥ ${ String.format( Locale.CHINA, "%.2f", expenseAmount ) }" else "暂无", color = Color.Gray, fontSize = 14.sp, modifier = Modifier.width(80.dp), textAlign = TextAlign.End ) }
Spacer(modifier = Modifier.height(12.dp))
// Income Row Row( modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically ) { Text( text = incomeLabel, color = Color.Gray, fontSize = 14.sp, modifier = Modifier.width(60.dp) ) Spacer(modifier = Modifier.width(8.dp)) Box( modifier = Modifier .weight(1f) .height(8.dp) .background(Color.Gray.copy(alpha = 0.5f), RoundedCornerShape(4.dp)) ) { Box( modifier = Modifier .fillMaxHeight() .fillMaxWidth(incFraction) .background(Color(0xFF4CAF50), RoundedCornerShape(4.dp)) ) } Spacer(modifier = Modifier.width(8.dp)) Text( text = if (incomeAmount > 0) "¥ ${ String.format( Locale.CHINA, "%.2f", incomeAmount ) }" else "暂无", color = Color.Gray, fontSize = 14.sp, modifier = Modifier.width(80.dp), textAlign = TextAlign.End ) } } } }

