import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.text.drawText
import androidx.compose.ui.text.rememberTextMeasurer
import kotlin.math.cos
import kotlin.math.sin
import java.time.DayOfWeek
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneId
import java.time.temporal.TemporalAdjusters
import java.util.Locale

data class ChartData(val label: String, val value: Double)

fun DayOfWeek.toChinese(): String = when (this) {
    DayOfWeek.MONDAY -> "周一"
    DayOfWeek.TUESDAY -> "周二"
    DayOfWeek.WEDNESDAY -> "周三"
    DayOfWeek.THURSDAY -> "周四"
    DayOfWeek.FRIDAY -> "周五"
    DayOfWeek.SATURDAY -> "周六"
    DayOfWeek.SUNDAY -> "周日"
}

@Composable
fun DailyStatisticView(
    viewModel: StatisticPage_VM = hiltViewModel(),
    backStack: NavBackStack<NavKey>? = null
) {
    val allBills by viewModel.allBills.collectAsState(initial = emptyList())

    var isExpense by remember { mutableStateOf(true) }
    var isLast7Days by remember { mutableStateOf(true) }
    var isExpanded by remember { mutableStateOf(false) }

    val primaryColor = MaterialTheme.colorScheme.primary


    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(vertical = 16.dp)
            .verticalScroll(viewModel.dailyScrollState)
    ) {
        androidx.compose.material3.Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 8.dp),
            elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 16.dp)
            ) {
                // Header
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Row(
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable(onClick = {
                                isLast7Days = !isLast7Days
                            })
                        ) {
                            Text(
                                text =
                                    if (isLast7Days) "近七天统计" else "本周的统计",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.width(2.dp))
                            Icon(
                                imageVector = if (isLast7Days) Icons.Default.SwipeUp else Icons.Default.SwipeDown,
                                contentDescription = "Swap Dates",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier
                                    .size(16.dp)
                                    .padding(0.dp)
                            )
                        }
                        IconButton(
                            onClick = { isExpanded = !isExpanded },
                        ) {
                            Icon(
                                imageVector = if (isExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                contentDescription = "Toggle Details",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier
                                    .size(16.dp)
                                    .padding(0.dp)
                            )
                        }
                    }

                    // Togge
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .border(1.dp, primaryColor, RoundedCornerShape(8.dp))
                    ) {
                        val expenseBgColor by animateColorAsState(
                            if (isExpense) primaryColor else MaterialTheme.colorScheme.surface,
                            label = "ExpenseBg"
                        )
                        val expenseTextColor by animateColorAsState(
                            if (isExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                            label = "ExpenseText"
                        )
                        val incomeBgColor by animateColorAsState(
                            if (!isExpense) primaryColor else MaterialTheme.colorScheme.surface,
                            label = "IncomeBg"
                        )
                        val incomeTextColor by animateColorAsState(
                            if (!isExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                            label = "IncomeText"
                        )

                        Box(
                            modifier = Modifier
                                .background(expenseBgColor)
                                .clickable { isExpense = true }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "支出",
                                color = expenseTextColor,
                                fontWeight = if (isExpense) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 12.sp
                            )
                        }
                        Box(
                            modifier = Modifier
                                .background(incomeBgColor)
                                .clickable { isExpense = false }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "收入",
                                color = incomeTextColor,
                                fontWeight = if (!isExpense) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 12.sp
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(32.dp))

                AnimatedContent(
                    targetState = Pair(isExpense, isLast7Days),
                    transitionSpec = {
                        fadeIn(animationSpec = tween(400)) togetherWith fadeOut(
                            animationSpec = tween(
                                400
                            )
                        )
                    },
                    label = "DailyContentAnim"
                ) { (targetIsExpense, targetIsLast7Days) ->

                    var targetStartAnimation by remember { mutableStateOf(false) }
                    LaunchedEffect(Unit) {
                        targetStartAnimation = true
                    }

                    val localDates = remember(targetIsLast7Days) {
                        if (targetIsLast7Days) {
                            (6 downTo 0).map { LocalDate.now().minusDays(it.toLong()) }
                        } else {
                            val monday =
                                LocalDate.now()
                                    .with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY))
                            (0..6).map { monday.plusDays(it.toLong()) }
                        }
                    }

                    val localChartData = remember(targetIsExpense, localDates, allBills) {
                        val typeToFilter =
                            if (targetIsExpense) BillType.EXPENSE else BillType.INCOME
                        val aggregatedData = allBills
                            .filter { it.type == typeToFilter }
                            .groupBy {
                                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                                    .toLocalDate()
                            }
                            .mapValues { (_, bills) -> bills.sumOf { it.amount } }

                        localDates.map { date ->
                            val dayStr =
                                if (targetIsLast7Days && date == LocalDate.now()) "今天" else date.dayOfWeek.toChinese()
                            val value = aggregatedData[date] ?: 0.0
                            ChartData(dayStr, value)
                        }
                    }

                    val localTotal = localChartData.sumOf { it.value }
                    val localAvg =
                        if (localChartData.isNotEmpty()) localTotal / localChartData.size else 0.0

                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp)
                    ) {
                        // Chart Area
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(210.dp)
                                .padding(8.dp)
                        ) {
                            if (localChartData.isNotEmpty()) {
                                Column(modifier = Modifier.fillMaxSize()) {
                                    Row(
                                        modifier = Modifier
                                            .weight(1f)
                                            .fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceEvenly,
                                        verticalAlignment = Alignment.Bottom
                                    ) {
                                        val maxValue = localChartData.maxOfOrNull { it.value }
                                            ?.takeIf { it > 0 } ?: 1.0
                                        val barColor =
                                            if (targetIsExpense) Color(0xFFF44336) else Color(
                                                0xFF4CAF50
                                            )

                                        localChartData.forEach { data ->
                                            val fraction = (data.value / maxValue).toFloat()
                                                .coerceAtLeast(0.01f)
                                            val isZero = data.value == 0.0

                                            val animFraction by animateFloatAsState(
                                                targetValue = if (targetStartAnimation && !isZero) fraction else 0f,
                                                animationSpec = spring(
                                                    dampingRatio = Spring.DampingRatioMediumBouncy,
                                                    stiffness = Spring.StiffnessLow
                                                ),
                                                label = "BarAnim"
                                            )

                                            Column(
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.Bottom,
                                                modifier = Modifier
                                                    .weight(1f)
                                                    .fillMaxHeight()
                                            ) {
                                                if (!isZero) {
                                                    Text(
                                                        text = if (data.value % 1.0 == 0.0) data.value.toInt()
                                                            .toString() else String.format(
                                                            Locale.getDefault(),
                                                            "%.1f",
                                                            data.value
                                                        ),
                                                        fontSize = 10.sp,
                                                        color = Color.Gray
                                                    )
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Box(
                                                    modifier = Modifier
                                                        .fillMaxWidth(0.6f)
                                                        .weight(1f, fill = false)
                                                        .fillMaxHeight(animFraction)
                                                        .clip(
                                                            RoundedCornerShape(
                                                                topStart = 6.dp,
                                                                topEnd = 6.dp,
                                                                bottomStart = 2.dp,
                                                                bottomEnd = 2.dp
                                                            )
                                                        )
                                                        .background(barColor)
                                                )
                                            }
                                        }
                                    }

                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(1.dp)
                                            .background(Color.LightGray.copy(alpha = 0.5f))
                                    )
                                    Spacer(modifier = Modifier.height(8.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceEvenly
                                    ) {
                                        localChartData.forEach { data ->
                                            Text(
                                                text = data.label,
                                                fontSize = 10.sp,
                                                color = Color.Gray,
                                                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                                lineHeight = 12.sp,
                                                modifier = Modifier.weight(1f)
                                            )
                                        }
                                    }
                                }
                            }
                        }

                        AnimatedVisibility(
                            visible = isExpanded,
                            enter = expandVertically() + fadeIn(),
                            exit = shrinkVertically() + fadeOut()
                        ) {
                            Column {
                                Spacer(modifier = Modifier.height(16.dp))
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 16.dp, vertical = 8.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Column {
                                        Text("总金额", color = Color.Gray, fontSize = 12.sp)
                                        Text(
                                            text = String.format("¥ %.2f", localTotal),
                                            fontSize = 18.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                    Column {
                                        Text("日均金额", color = Color.Gray, fontSize = 12.sp)
                                        Text(
                                            text = String.format("¥ %.2f", localAvg),
                                            fontSize = 18.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        var isPiePercentageMode by remember { mutableStateOf(true) }
        var isPieExpanded by remember { mutableStateOf(true) }
        var isPieExpense by remember { mutableStateOf(true) }

        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 8.dp),
            elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 16.dp)
            ) {
                // Header
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Row(
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.clickable(onClick = {
                                isPiePercentageMode = !isPiePercentageMode
                            })
                        ) {
                            Text(
                                text = "分类占比",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.width(2.dp))
                            Icon(
                                imageVector = if (isPiePercentageMode) Icons.Default.SwipeUp else Icons.Default.SwipeDown,
                                contentDescription = "Swap Mode",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier
                                    .size(16.dp)
                                    .padding(0.dp)
                            )
                        }
                        IconButton(
                            onClick = { isPieExpanded = !isPieExpanded },
                        ) {
                            Icon(
                                imageVector = if (isPieExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                contentDescription = "Toggle Details",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier
                                    .size(16.dp)
                                    .padding(0.dp)
                            )
                        }
                    }

                    // Togge
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .border(1.dp, primaryColor, RoundedCornerShape(8.dp))
                    ) {
                        val expenseBgColor by animateColorAsState(
                            if (isPieExpense) primaryColor else MaterialTheme.colorScheme.surface,
                            label = "ExpenseBg"
                        )
                        val expenseTextColor by animateColorAsState(
                            if (isPieExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                            label = "ExpenseText"
                        )
                        val incomeBgColor by animateColorAsState(
                            if (!isPieExpense) primaryColor else MaterialTheme.colorScheme.surface,
                            label = "IncomeBg"
                        )
                        val incomeTextColor by animateColorAsState(
                            if (!isPieExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                            label = "IncomeText"
                        )

                        Box(
                            modifier = Modifier
                                .background(expenseBgColor)
                                .clickable { isPieExpense = true }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "支出",
                                color = expenseTextColor,
                                fontWeight = if (isPieExpense) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 12.sp
                            )
                        }
                        Box(
                            modifier = Modifier
                                .background(incomeBgColor)
                                .clickable { isPieExpense = false }
                                .padding(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Text(
                                text = "收入",
                                color = incomeTextColor,
                                fontWeight = if (!isPieExpense) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 12.sp
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                val localDates = remember(isLast7Days) {
                    if (isLast7Days) {
                        (6 downTo 0).map { LocalDate.now().minusDays(it.toLong()) }
                    } else {
                        val monday = LocalDate.now()
                            .with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY))
                        (0..6).map { monday.plusDays(it.toLong()) }
                    }
                }
                val typeToFilter = if (isPieExpense) BillType.EXPENSE else BillType.INCOME

                val pieBills = allBills.filter { bill ->
                    val billDate =
                        Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                            .toLocalDate()
                    bill.type == typeToFilter && localDates.contains(billDate)
                }
                val totalPieAmount = pieBills.sumOf { it.amount }
                val categoryGroups = pieBills.groupBy { it.category }
                    .mapValues { it.value.sumOf { b -> b.amount } }
                    .toList()
                    .sortedByDescending { it.second }

                val colors = listOf(
                    Color(0xFFF44336), Color(0xFF2196F3), Color(0xFFFF9800),
                    Color(0xFF4CAF50), Color(0xFF9C27B0), Color(0xFF00BCD4),
                    Color(0xFFFFEB3B), Color(0xFF795548)
                )

                Column(modifier = Modifier.fillMaxWidth()) {
                    if (categoryGroups.isNotEmpty() && totalPieAmount > 0) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(300.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            val amountText1 =
                                String.format(Locale.getDefault(), "%.2f", totalPieAmount)
                            val amountText2 = if (isPieExpense) "总支出" else "总收入"

                            CustomDonutChart(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(16.dp),
                                data = categoryGroups,
                                colors = colors,
                                totalAmount = totalPieAmount,
                                centerTitle = amountText1,
                                centerSubtitle = amountText2,
                                isPercentageMode = isPiePercentageMode
                            )
                        }

                        AnimatedVisibility(
                            visible = isPieExpanded,
                            enter = expandVertically() + fadeIn(),
                            exit = shrinkVertically() + fadeOut()
                        ) {
                            Column(modifier = Modifier.fillMaxWidth()) {
                                Spacer(modifier = Modifier.height(24.dp))

                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 16.dp)
                                ) {
                                    val safeCategoryList = qzwx.app.module_ui.data.billCategoryList + qzwx.app.module_ui.data.incomeCategoryList
                                    categoryGroups.forEachIndexed { index, pair ->
                                        val percent = (pair.second / totalPieAmount) * 100
                                        val cat = safeCategoryList.find { it.name == pair.first }
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable(enabled = backStack != null) {
                                                    backStack?.add(
                                                        qzwx.app.module_ui.nav3.UIRoute.CategoryBills(
                                                            pair.first,
                                                            pieBills.filter { it.category == pair.first }
                                                        )
                                                    )
                                                }
                                                .padding(vertical = 8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            if (cat != null) {
                                                Icon(
                                                    imageVector = cat.icon,
                                                    contentDescription = cat.name,
                                                    tint = colors[index % colors.size],
                                                    modifier = Modifier.size(32.dp)
                                                )
                                            } else {
                                                Box(
                                                    modifier = Modifier
                                                        .size(32.dp)
                                                        .background(
                                                            colors[index % colors.size],
                                                            RoundedCornerShape(50)
                                                        )
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(16.dp))
                                            Column(modifier = Modifier.weight(1f)) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    Text(
                                                        text = pair.first,
                                                        fontSize = 14.sp,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                    Text(
                                                        text = "¥${
                                                            String.format(
                                                                Locale.getDefault(),
                                                                "%.2f",
                                                                pair.second
                                                            )
                                                        }", fontSize = 14.sp, fontWeight = FontWeight.Bold
                                                    )
                                                }
                                                Spacer(modifier = Modifier.height(4.dp))
                                                LinearProgressIndicator(
                                                    progress = { (percent / 100).toFloat() },
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .height(8.dp)
                                                        .clip(RoundedCornerShape(4.dp)),
                                                    color = colors[index % colors.size],
                                                    trackColor = MaterialTheme.colorScheme.surfaceVariant
                                                )
                                                Spacer(modifier = Modifier.height(4.dp))
                                                Text(
                                                    text = "${
                                                        String.format(
                                                            Locale.getDefault(),
                                                            "%.1f",
                                                            percent
                                                        )
                                                    }%", fontSize = 12.sp, color = Color.Gray
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(180.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = "没有记录",
                                color = Color.Gray,
                                fontSize = 14.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun StatisticThreeWayToggle(
    selectedType: Int, // 0: 支出, 1: 收入, 2: 混合
    onTypeSelected: (Int) -> Unit,
    primaryColor: Color,
    surfaceColor: Color
) {
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(8.dp))
            .border(1.dp, primaryColor, RoundedCornerShape(8.dp))
    ) {
        val types = listOf("支出", "收入", "混合")
        types.forEachIndexed { index, title ->
            val isSelected = selectedType == index
            val bgColor by animateColorAsState(
                if (isSelected) primaryColor else surfaceColor,
                label = "ToggleBg$index"
            )
            val textColor by animateColorAsState(
                if (isSelected) MaterialTheme.colorScheme.onPrimary else primaryColor,
                label = "ToggleText$index"
            )
            Box(
                modifier = Modifier
                    .background(bgColor)
                    .clickable { onTypeSelected(index) }
                    .padding(horizontal = 12.dp, vertical = 4.dp)
            ) {
                Text(
                    text = title,
                    color = textColor,
                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                    fontSize = 12.sp
                )
            }
        }
    }
}

@Composable
fun MonthlyStatisticView(
    viewModel: StatisticPage_VM = hiltViewModel(),
    backStack: NavBackStack<NavKey>? = null
) {
    val selectedDate by viewModel.selectedMonth.collectAsState()
    val monthlyState by viewModel.monthlyChartState.collectAsState(initial = MonthlyChartState())
    val allBills by viewModel.allBills.collectAsState(initial = emptyList())

    var isPieChartExpense by remember { mutableStateOf(true) }

    var barChartType by remember {
        mutableStateOf(0) // 0: 支出, 1: 收入, 2: 混合
    }
    var lineChartType by remember {
        mutableStateOf(0) // 0: 支出, 1: 收入, 2: 混合
    }
    val backgroundColor = MaterialTheme.colorScheme.background
    val primaryColor = MaterialTheme.colorScheme.primary
    val errorColor = MaterialTheme.colorScheme.error
    val surfaceColor = MaterialTheme.colorScheme.surface
    val primaryContainer = MaterialTheme.colorScheme.primaryContainer
    val onPrimaryContainer = MaterialTheme.colorScheme.onPrimaryContainer

    val monthsList = remember {
        (0..24).map { LocalDate.now().withDayOfMonth(1).minusMonths(it.toLong()) }
    }

    var selectedPieCategory by remember { mutableStateOf<String?>(null) }

    LazyColumn(
        state = viewModel.monthlyListState,
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .padding(vertical = 16.dp)
    ) {
        item {
            // Year and Month LazyRow Header
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
            ) {
                Text(
                    text = "${selectedDate.year}年",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                LazyRow(
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    itemsIndexed(monthsList) { _, monthDate ->
                        val isSelected = selectedDate == monthDate
                        val todayM = LocalDate.now().withDayOfMonth(1)
                        val titleStr = when {
                            monthDate == todayM -> "本月"
                            monthDate == todayM.minusMonths(1) -> "上月"
                            monthDate.year == todayM.year - 1 && monthDate.monthValue == 12 -> "去年12月"
                            else -> "${monthDate.monthValue}月"
                        }

                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(16.dp))
                                .background(if (isSelected) primaryColor else surfaceColor)
                                .clickable {
                                    viewModel.selectMonth(monthDate)
                                }
                                .border(
                                    width = 1.dp,
                                    color = if (isSelected) primaryColor else Color.LightGray,
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .padding(horizontal = 16.dp, vertical = 6.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = titleStr,
                                color = if (isSelected) MaterialTheme.colorScheme.onPrimary else Color.Gray,
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 14.sp
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            AnimatedContent(
                targetState = selectedDate,
                transitionSpec = {
                    fadeIn(animationSpec = tween(400)) togetherWith fadeOut(
                        animationSpec = tween(
                            400
                        )
                    )
                },
                label = "MonthlyContentAnim"
            ) { targetDate ->
                Column {
                    // Summary Card
                    qzwx.app.module_ui.components.Shared_SummaryCard(
                        expenseLabel = "月支出",
                        expenseAmount = monthlyState.monthExpense, // Note: these are derived from state based on selected month
                        incomeLabel = "月收入",
                        incomeAmount = monthlyState.monthIncome,
                        balanceLabel = "月结余",
                        balanceAmount = monthlyState.monthBalance
                    )

                    Spacer(modifier = Modifier.height(24.dp))

                    // Chart Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(text = "收支统计", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                        StatisticThreeWayToggle(
                            selectedType = barChartType,
                            onTypeSelected = { barChartType = it },
                            primaryColor = primaryColor,
                            surfaceColor = surfaceColor
                        )
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    val filteredBarDataList = remember(monthlyState.barDataList, barChartType) {
                        monthlyState.barDataList.map { bar ->
                            val newValues = when (barChartType) {
                                0 -> listOf(bar.values.getOrNull(0)).filterNotNull()
                                1 -> listOf(bar.values.getOrNull(1)).filterNotNull()
                                else -> bar.values
                            }
                            bar.copy(values = newValues)
                        }
                    }

                    // Chart
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(260.dp)
                            .padding(horizontal = 16.dp)
                    ) {
                        if (monthlyState.isReady && filteredBarDataList.isNotEmpty()) {
                            ColumnChart(
                                animationDelay = 5,
                                modifier = Modifier.fillMaxSize(),
                                data = filteredBarDataList,
                                barProperties = BarProperties(
                                    spacing = 2.dp,
                                    cornerRadius = Bars.Data.Radius.Rectangle(
                                        topRight = 4.dp,
                                        topLeft = 4.dp
                                    ),
                                    thickness = 4.dp
                                ),
                                labelProperties = LabelProperties(
                                    enabled = true,
                                    textStyle = TextStyle(fontSize = 9.sp),
                                    rotation = LabelProperties.Rotation(
                                        degree = 0f
                                    )
                                ),
                                indicatorProperties = HorizontalIndicatorProperties(
                                    enabled = false,
                                    textStyle = TextStyle(fontSize = 9.sp)
                                ),
                                gridProperties = GridProperties(
                                    xAxisProperties = GridProperties.AxisProperties(enabled = false),
                                    yAxisProperties = GridProperties.AxisProperties(
                                        enabled = true, color = SolidColor(
                                            Color.LightGray.copy(alpha = 0.5f)
                                        )
                                    )
                                ),
                                animationSpec = spring(
                                    dampingRatio = Spring.DampingRatioMediumBouncy,
                                    stiffness = Spring.StiffnessLow
                                )
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))

                    // Line Chart Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(text = "收支趋势", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                        StatisticThreeWayToggle(
                            selectedType = lineChartType,
                            onTypeSelected = { lineChartType = it },
                            primaryColor = primaryColor,
                            surfaceColor = surfaceColor
                        )
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    val filteredLineChartData =
                        remember(monthlyState.theLineChartData, lineChartType) {
                            when (lineChartType) {
                                0 -> monthlyState.theLineChartData.filter { it.label == "支出" }
                                1 -> monthlyState.theLineChartData.filter { it.label == "收入" }
                                else -> monthlyState.theLineChartData
                            }
                        }

                    // Line Chart
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(260.dp)
                            .padding(horizontal = 16.dp)
                    ) {
                        if (monthlyState.isReady && filteredLineChartData.isNotEmpty()) {
                            LineChart(
                                modifier = Modifier.fillMaxSize(),
                                data = filteredLineChartData,
                                labelProperties = LabelProperties(
                                    rotation = LabelProperties.Rotation(
                                        degree = 0f
                                    ),
                                    enabled = true,
                                    labels = (1..selectedDate.lengthOfMonth()).map { if (it % 2 != 0) it.toString() else " " },
                                    textStyle = TextStyle(fontSize = 9.sp)
                                ),
                                indicatorProperties = HorizontalIndicatorProperties(
                                    enabled = false,
                                    textStyle = TextStyle(fontSize = 9.sp)
                                ),
                                gridProperties = GridProperties(
                                    xAxisProperties = GridProperties.AxisProperties(enabled = false),
                                    yAxisProperties = GridProperties.AxisProperties(
                                        enabled = true, color = SolidColor(
                                            Color.LightGray.copy(alpha = 0.5f)
                                        )
                                    )
                                ),
                                curvedEdges = false
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))

                    val monthlyBillsForPie = allBills.filter { bill ->
                        val date =
                            Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                                .toLocalDate()
                        date.year == targetDate.year && date.month == targetDate.month
                    }
                    qzwx.app.module_ui.components.Shared_CategoryPieChart(
                        bills = monthlyBillsForPie,
                        onCategoryClick = { categoryName, categoryBills ->
                            backStack?.add(
                                qzwx.app.module_ui.nav3.UIRoute.CategoryBills(
                                    categoryName,
                                    categoryBills
                                )
                            )
                        }
                    )
                }
            }
        }
    }
}

@Composable
fun YearlyStatisticView(
    viewModel: StatisticPage_VM = hiltViewModel(),
    backStack: NavBackStack<NavKey>? = null
) {
    val allBills by viewModel.allBills.collectAsState(initial = emptyList())

    var selectedYear by remember { mutableStateOf(LocalDate.now().year) }
    var isHeatmapExpense by remember { mutableStateOf(true) }
    var isYearlyPieChartExpense by remember { mutableStateOf(true) }
    var selectedYearlyPieCategory by remember { mutableStateOf<String?>(null) }

    val primaryColor = MaterialTheme.colorScheme.primary
    val surfaceColor = MaterialTheme.colorScheme.surface
    val primaryContainer = MaterialTheme.colorScheme.primaryContainer
    val onPrimaryContainer = MaterialTheme.colorScheme.onPrimaryContainer
    val errorColor = MaterialTheme.colorScheme.error
    val backgoundColor = MaterialTheme.colorScheme.background
    val yearsList = remember {
        (0..19).map { LocalDate.now().year - it }
    }

    val yearlyBills = remember(allBills, selectedYear) {
        allBills.filter { bill ->
            val date =
                Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault()).toLocalDate()
            date.year == selectedYear
        }
    }

    val yearExpense = remember(yearlyBills) {
        yearlyBills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
    }
    val yearIncome = remember(yearlyBills) {
        yearlyBills.filter { it.type == BillType.INCOME }.sumOf { it.amount }
    }
    val yearBalance = yearIncome - yearExpense

    LazyColumn(
        state = viewModel.yearlyListState,
        modifier = Modifier
            .fillMaxSize()
            .background(backgoundColor)
            .padding(vertical = 16.dp)
    ) {
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
            ) {
                LazyRow(
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    itemsIndexed(yearsList) { _, year ->
                        val isSelected = selectedYear == year
                        val currentYear = LocalDate.now().year
                        val titleStr = when (year) {
                            currentYear -> "今年"
                            currentYear - 1 -> "去年"
                            else -> "${year}年"
                        }

                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(16.dp))
                                .background(if (isSelected) primaryColor else surfaceColor)
                                .clickable {
                                    selectedYear = year
                                }
                                .border(
                                    width = 1.dp,
                                    color = if (isSelected) primaryColor else Color.LightGray,
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .padding(horizontal = 16.dp, vertical = 6.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = titleStr,
                                color = if (isSelected) MaterialTheme.colorScheme.onPrimary else Color.Gray,
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                                fontSize = 14.sp
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            AnimatedContent(
                targetState = selectedYear,
                transitionSpec = {
                    fadeIn(animationSpec = tween(400)) togetherWith fadeOut(
                        animationSpec = tween(
                            400
                        )
                    )
                },
                label = "YearlyContentAnim"
            ) { targetYear ->

                val targetYearlyBills = allBills.filter { bill ->
                    val date = Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                        .toLocalDate()
                    date.year == targetYear
                }
                val targetYearExpense =
                    targetYearlyBills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
                val targetYearIncome =
                    targetYearlyBills.filter { it.type == BillType.INCOME }.sumOf { it.amount }
                val targetYearBalance = targetYearIncome - targetYearExpense

                Column {
                    // Summary Card
                    qzwx.app.module_ui.components.Shared_SummaryCard(
                        expenseLabel = "年支出",
                        expenseAmount = targetYearExpense,
                        incomeLabel = "年收入",
                        incomeAmount = targetYearIncome,
                        balanceLabel = "年结余",
                        balanceAmount = targetYearBalance
                    )

                    Spacer(modifier = Modifier.height(24.dp))

                    // Heatmap Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(text = "收支热力", fontSize = 18.sp, fontWeight = FontWeight.Bold)

                        Row(
                            modifier = Modifier
                                .clip(RoundedCornerShape(8.dp))
                                .border(1.dp, primaryColor, RoundedCornerShape(8.dp))
                        ) {
                            val heatExpenseBgColor by animateColorAsState(
                                if (isHeatmapExpense) primaryColor else surfaceColor,
                                label = "HeatExpenseBg"
                            )
                            val heatExpenseTextColor by animateColorAsState(
                                if (isHeatmapExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                                label = "HeatExpenseText"
                            )
                            val heatIncomeBgColor by animateColorAsState(
                                if (!isHeatmapExpense) primaryColor else surfaceColor,
                                label = "HeatIncomeBg"
                            )
                            val heatIncomeTextColor by animateColorAsState(
                                if (!isHeatmapExpense) MaterialTheme.colorScheme.onPrimary else primaryColor,
                                label = "HeatIncomeText"
                            )

                            Box(
                                modifier = Modifier
                                    .background(heatExpenseBgColor)
                                    .clickable { isHeatmapExpense = true }
                                    .padding(horizontal = 16.dp, vertical = 6.dp)
                            ) {
                                Text(
                                    text = "支出",
                                    color = heatExpenseTextColor,
                                    fontWeight = if (isHeatmapExpense) FontWeight.Bold else FontWeight.Normal,
                                    fontSize = 12.sp
                                )
                            }
                            Box(
                                modifier = Modifier
                                    .background(heatIncomeBgColor)
                                    .clickable { isHeatmapExpense = false }
                                    .padding(horizontal = 16.dp, vertical = 6.dp)
                            ) {
                                Text(
                                    text = "收入",
                                    color = heatIncomeTextColor,
                                    fontWeight = if (!isHeatmapExpense) FontWeight.Bold else FontWeight.Normal,
                                    fontSize = 12.sp
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    // Heatmap Grid
                    AnimatedContent(
                        targetState = isHeatmapExpense,
                        transitionSpec = {
                            fadeIn(animationSpec = tween(400)) togetherWith fadeOut(
                                animationSpec = tween(
                                    400
                                )
                            )
                        },
                        label = "HeatmapContentAnim"
                    ) { targetIsExpense ->
                        val typeToFilter =
                            if (targetIsExpense) BillType.EXPENSE else BillType.INCOME
                        val activeColor =
                            if (targetIsExpense) Color(0xFFF44336) else Color(0xFF4CAF50)
                        val inactiveColor = Color(0xFFEEEEEE)

                        val heatBills = targetYearlyBills.filter { it.type == typeToFilter }
                        val billDates = heatBills.map {
                            Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                                .toLocalDate()
                        }.toSet()

                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            for (row in 0 until 3) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    for (col in 0 until 4) {
                                        val monthIndex = row * 4 + col + 1
                                        val isLeap = java.time.Year.isLeap(targetYear.toLong())
                                        val daysInMonth =
                                            java.time.Month.of(monthIndex).length(isLeap)
                                        val firstDateOfMonth =
                                            LocalDate.of(targetYear, monthIndex, 1)
                                        val firstDayOfWeek =
                                            firstDateOfMonth.dayOfWeek.value // 1 (Mon) - 7 (Sun)

                                        Column(
                                            modifier = Modifier.weight(1f),
                                            horizontalAlignment = Alignment.Start
                                        ) {
                                            Text(
                                                text = "${monthIndex}月",
                                                fontSize = 12.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(
                                                    bottom = 6.dp,
                                                    start = 2.dp
                                                )
                                            )
                                            // Draw month mini calendar map
                                            val weeks =
                                                Math.ceil((daysInMonth + firstDayOfWeek - 1) / 7.0)
                                                    .toInt()
                                            for (w in 0 until 6) { // Draw exactly 6 rows to keep all month grids equal height
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween
                                                ) {
                                                    for (d in 1..7) {
                                                        val dayIndex = w * 7 + d
                                                        val dateDay = dayIndex - firstDayOfWeek + 1
                                                        if (dateDay in 1..daysInMonth) {
                                                            val currentDate = LocalDate.of(
                                                                targetYear,
                                                                monthIndex,
                                                                dateDay
                                                            )
                                                            val cellColor =
                                                                if (billDates.contains(currentDate)) activeColor else inactiveColor
                                                            Box(
                                                                modifier = Modifier
                                                                    .weight(1f)
                                                                    .aspectRatio(1f)
                                                                    .padding(1.dp)
                                                                    .clip(RoundedCornerShape(50))
                                                                    .background(cellColor)
                                                            )
                                                        } else {
                                                            // Empty cell space maintaining proportion
                                                            Box(
                                                                modifier = Modifier
                                                                    .weight(1f)
                                                                    .aspectRatio(1f)
                                                                    .padding(1.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                if (row < 2) {
                                    Spacer(modifier = Modifier.height(8.dp))
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))


                    qzwx.app.module_ui.components.Shared_CategoryPieChart(
                        bills = targetYearlyBills,
                        onCategoryClick = { categoryName, categoryBills ->
                            backStack?.add(
                                qzwx.app.module_ui.nav3.UIRoute.CategoryBills(
                                    categoryName,
                                    categoryBills
                                )
                            )
                        }
                    )

                    Spacer(modifier = Modifier.height(24.dp))

                    // Multi-year Bar Chart Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(text = "历年收支", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                        qzwx.app.module_ui.components.Shared_ChartLegend()
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    val maxAmount = remember(allBills) {
                        yearsList.maxOfOrNull { year ->
                            val bills = allBills.filter {
                                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                                    .toLocalDate().year == year
                            }
                            val e = bills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
                            val i = bills.filter { it.type == BillType.INCOME }.sumOf { it.amount }
                            maxOf(e, i)
                        }?.takeIf { it > 0 } ?: 1.0
                    }

                    var startChartAnimation by remember { mutableStateOf(false) }
                    LaunchedEffect(Unit) { startChartAnimation = true }

                    val screenWidth = LocalConfiguration.current.screenWidthDp.dp
                    val itemWidth = screenWidth / 5

                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(240.dp),
                        horizontalArrangement = Arrangement.Start,
                        verticalAlignment = Alignment.Bottom,
                        reverseLayout = true
                    ) {
                        items(yearsList) { year ->
                            val bills = allBills.filter {
                                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                                    .toLocalDate().year == year
                            }
                            val expense =
                                bills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
                            val income =
                                bills.filter { it.type == BillType.INCOME }.sumOf { it.amount }

                            val expFraction =
                                if (startChartAnimation && expense > 0) (expense / maxAmount).toFloat()
                                    .coerceAtLeast(0.02f) else 0f
                            val incFraction =
                                if (startChartAnimation && income > 0) (income / maxAmount).toFloat()
                                    .coerceAtLeast(0.02f) else 0f

                            val expAnim by animateFloatAsState(
                                targetValue = expFraction,
                                animationSpec = spring(
                                    dampingRatio = Spring.DampingRatioMediumBouncy,
                                    stiffness = Spring.StiffnessLow
                                ),
                                label = "ExpAnim"
                            )
                            val incAnim by animateFloatAsState(
                                targetValue = incFraction,
                                animationSpec = spring(
                                    dampingRatio = Spring.DampingRatioMediumBouncy,
                                    stiffness = Spring.StiffnessLow
                                ),
                                label = "IncAnim"
                            )

                            Column(
                                modifier = Modifier
                                    .width(itemWidth)
                                    .fillMaxHeight(),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Bottom
                            ) {
                                Row(
                                    verticalAlignment = Alignment.Bottom,
                                    horizontalArrangement = Arrangement.Center,
                                    modifier = Modifier
                                        .weight(1f)
                                        .fillMaxWidth()
                                ) {
                                    // Expense Bar
                                    Column(
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.Bottom,
                                        modifier = Modifier
                                            .width(20.dp)
                                            .fillMaxHeight()
                                    ) {
                                        if (expense > 0) {
                                            Text(
                                                text = if (expense % 1.0 == 0.0) expense.toInt()
                                                    .toString() else String.format(
                                                    Locale.getDefault(),
                                                    "%.1f",
                                                    expense
                                                ),
                                                fontSize = 9.sp,
                                                color = Color.Gray,
                                                modifier = Modifier.wrapContentWidth(unbounded = true)
                                            )
                                            Spacer(modifier = Modifier.height(4.dp))
                                        }
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .fillMaxHeight(expAnim)
                                                .background(
                                                    Color(0xFFF44336),
                                                    RoundedCornerShape(
                                                        topStart = 4.dp,
                                                        topEnd = 4.dp
                                                    )
                                                )
                                        )
                                    }

                                    // Income Bar
                                    Column(
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.Bottom,
                                        modifier = Modifier
                                            .width(20.dp)
                                            .fillMaxHeight()
                                    ) {
                                        if (income > 0) {
                                            Text(
                                                text = if (income % 1.0 == 0.0) income.toInt()
                                                    .toString() else String.format(
                                                    Locale.getDefault(),
                                                    "%.1f",
                                                    income
                                                ),
                                                fontSize = 9.sp,
                                                color = Color.Gray,
                                                modifier = Modifier.wrapContentWidth(unbounded = true)
                                            )
                                            Spacer(modifier = Modifier.height(4.dp))
                                        }
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .fillMaxHeight(incAnim)
                                                .background(
                                                    Color(0xFF4CAF50),
                                                    RoundedCornerShape(
                                                        topStart = 4.dp,
                                                        topEnd = 4.dp
                                                    )
                                                )
                                        )
                                    }
                                }
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(1.dp)
                                        .background(Color.LightGray.copy(alpha = 0.5f))
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = "${year}年",
                                    fontSize = 10.sp,
                                    color = Color.Gray
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomStatisticView(
    viewModel: StatisticPage_VM = hiltViewModel(),
    backStack: NavBackStack<NavKey>? = null
) {
    val allBills by viewModel.allBills.collectAsState(initial = emptyList())

    val calendarState = rememberUseCaseState()

    var startDate by remember { mutableStateOf(LocalDate.now().minusDays(30)) }
    var endDate by remember { mutableStateOf(LocalDate.now()) }

    var lineChartType by remember {
        mutableStateOf(0) // 0: 支出, 1: 收入, 2: 混合
    }

    val primaryColor = MaterialTheme.colorScheme.primary
    val surfaceColor = MaterialTheme.colorScheme.surface
    val backgroundColor = MaterialTheme.colorScheme.background
    CalendarDialog(
        state = calendarState,
        config = CalendarConfig(
            yearSelection = true,
            monthSelection = true
        ),
        selection = CalendarSelection.Period { start, end ->
            startDate = start
            endDate = end
        }
    )

    LazyColumn(
        state = viewModel.customListState,
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .padding(vertical = 16.dp)
    ) {
        item {
            // Header
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Spacer(modifier = Modifier.weight(1f))
                Text(
                    text = "${startDate.year}年${startDate.monthValue}月${startDate.dayOfMonth}日 - ${endDate.year}年${endDate.monthValue}月${endDate.dayOfMonth}日",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurface
                )
                Spacer(modifier = Modifier.weight(1f))
                Icon(
                    imageVector = Icons.Default.DateRange,
                    contentDescription = "Select Date Range",
                    tint = primaryColor,
                    modifier = Modifier
                        .padding(start = 8.dp)
                        .clickable { calendarState.show() }
                )
            }

            Spacer(modifier = Modifier.height(24.dp))

            val filteredBills = remember(allBills, startDate, endDate) {
                allBills.filter { bill ->
                    val date = Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                        .toLocalDate()
                    !date.isBefore(startDate) && !date.isAfter(endDate)
                }
            }

            val totalExpense = remember(filteredBills) {
                filteredBills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
            }

            val totalIncome = remember(filteredBills) {
                filteredBills.filter { it.type == BillType.INCOME }.sumOf { it.amount }
            }

            val totalBalance = totalIncome - totalExpense

            qzwx.app.module_ui.components.Shared_SummaryCard(
                expenseLabel = "总支出",
                expenseAmount = totalExpense,
                incomeLabel = "总收入",
                incomeAmount = totalIncome,
                balanceLabel = "总结余",
                balanceAmount = totalBalance
            )

            Spacer(modifier = Modifier.height(24.dp))

            // Line Chart Toggle
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(text = "收支趋势", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                StatisticThreeWayToggle(
                    selectedType = lineChartType,
                    onTypeSelected = { lineChartType = it },
                    primaryColor = primaryColor,
                    surfaceColor = surfaceColor
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            val dateList = remember(startDate, endDate) {
                val list = mutableListOf<LocalDate>()
                var current = startDate
                while (!current.isAfter(endDate)) {
                    list.add(current)
                    current = current.plusDays(1)
                }
                list
            }

            val expenseDataList = remember(filteredBills, dateList) {
                dateList.map { date ->
                    filteredBills.filter { bill ->
                        val billDate =
                            Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                                .toLocalDate()
                        billDate == date && bill.type == BillType.EXPENSE
                    }.sumOf { it.amount }
                }
            }

            val incomeDataList = remember(filteredBills, dateList) {
                dateList.map { date ->
                    filteredBills.filter { bill ->
                        val billDate =
                            Instant.ofEpochMilli(bill.createdAt).atZone(ZoneId.systemDefault())
                                .toLocalDate()
                        billDate == date && bill.type == BillType.INCOME
                    }.sumOf { it.amount }
                }
            }

            val lineChartDataList = remember(expenseDataList, incomeDataList, lineChartType) {
                val data = mutableListOf<Line>()
                if (lineChartType == 0 || lineChartType == 2) {
                    data.add(
                        Line(
                            label = "支出",
                            values = expenseDataList,
                            color = SolidColor(Color(0xFFF44336)),
                            firstGradientFillColor = Color(0xFFF44336).copy(alpha = 0.5f),
                            secondGradientFillColor = Color.Transparent,
                            strokeAnimationSpec = tween(2000, easing = EaseInOutCubic),
                            gradientAnimationDelay = 1000,
                            drawStyle = DrawStyle.Stroke(width = 2.dp)
                        )
                    )
                }
                if (lineChartType == 1 || lineChartType == 2) {
                    data.add(
                        Line(
                            label = "收入",
                            values = incomeDataList,
                            color = SolidColor(Color(0xFF4CAF50)),
                            firstGradientFillColor = Color(0xFF4CAF50).copy(alpha = 0.5f),
                            secondGradientFillColor = Color.Transparent,
                            strokeAnimationSpec = tween(2000, easing = EaseInOutCubic),
                            gradientAnimationDelay = 1000,
                            drawStyle = DrawStyle.Stroke(width = 2.dp)
                        )
                    )
                }
                data
            }

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(260.dp)
                    .padding(horizontal = 16.dp)
            ) {
                if (lineChartDataList.isNotEmpty() && dateList.isNotEmpty()) {
                    val labels = List(dateList.size) { index ->
                        if (index == 0) "${dateList.first().monthValue}-${dateList.first().dayOfMonth}"
                        else if (index == dateList.size - 1) "${dateList.last().monthValue}-${dateList.last().dayOfMonth}"
                        else " "
                    }

                    LineChart(
                        modifier = Modifier.fillMaxSize(),
                        data = lineChartDataList,
                        labelProperties = LabelProperties(
                            rotation = LabelProperties.Rotation(degree = 0f),
                            enabled = true,
                            labels = labels,
                            textStyle = TextStyle(
                                fontSize = 11.sp,
                                color = Color.Gray
                            )
                        ),
                        indicatorProperties = HorizontalIndicatorProperties(
                            enabled = false,
                        ),
                        gridProperties = GridProperties(
                            xAxisProperties = GridProperties.AxisProperties(enabled = false),
                            yAxisProperties = GridProperties.AxisProperties(enabled = false)
                        ),
                        curvedEdges = false
                    )
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            qzwx.app.module_ui.components.Shared_CategoryPieChart(
                bills = filteredBills,
                onCategoryClick = { categoryName, categoryBills ->
                    backStack?.add(
                        qzwx.app.module_ui.nav3.UIRoute.CategoryBills(
                            categoryName,
                            categoryBills
                        )
                    )
                }
            )
        }
    }
}

@Composable
fun CustomDonutChart(
    modifier: Modifier = Modifier,
    data: List<Pair<String, Double>>,
    colors: List<Color>,
    totalAmount: Double,
    centerTitle: String,
    centerSubtitle: String,
    isPercentageMode: Boolean = true
) {
    val animateRotation = remember { androidx.compose.animation.core.Animatable(0f) }

    // Restart animation whenever the list of bills (or expense/income mode) changes.
    LaunchedEffect(data) {
        animateRotation.snapTo(0f)
        animateRotation.animateTo(
            targetValue = 360f,
            animationSpec = tween(durationMillis = 1000, easing = FastOutSlowInEasing)
        )
    }

    // Add another alpha animation for indicator lines and texts that appears after pie is drawn
    val animateAlpha by animateFloatAsState(
        targetValue = if (animateRotation.value >= 360f) 1f else 0f,
        animationSpec = tween(durationMillis = 500, easing = LinearEasing),
        label = "donut_alpha"
    )

    val textMeasurer = rememberTextMeasurer()
    val centerTitleStyle = androidx.compose.ui.text.TextStyle(
        fontSize = 18.sp,
        fontWeight = FontWeight.Bold,
        color = MaterialTheme.colorScheme.onSurface
    )
    val centerSubtitleStyle = androidx.compose.ui.text.TextStyle(
        fontSize = 12.sp,
        color = Color.Gray
    )

    Canvas(modifier = modifier) {
        val sweepAngles = data.map { 360f * (it.second / totalAmount).toFloat() }
        val canvasSize = size.minDimension
        val center = Offset(size.width / 2, size.height / 2)
        // Shrunk chart pie size slightly to prevent indicators from visually overflowing
        val radius = canvasSize / 2 - 60.dp.toPx()
        val strokeWidth = 14.dp.toPx()

        var startAngle = -90f

        data.forEachIndexed { index, pair ->
            val sweepAngle = sweepAngles[index] * (animateRotation.value / 360f)
            val color = colors[index % colors.size]

            drawArc(
                color = color,
                startAngle = startAngle,
                sweepAngle = sweepAngle,
                useCenter = false,
                style = Stroke(width = strokeWidth),
                size = Size(radius * 2, radius * 2),
                topLeft = Offset(center.x - radius, center.y - radius)
            )

            if (animateAlpha > 0f) {
                // Draw indicating lines and text with opacity
                val angleInRadians = (startAngle + sweepAngle / 2) * (Math.PI / 180f)
                val lineLength1 = 15.dp.toPx()
                val lineLength2 = 25.dp.toPx()

                val x1 = center.x + (radius + strokeWidth / 2) * cos(angleInRadians).toFloat()
                val y1 = center.y + (radius + strokeWidth / 2) * sin(angleInRadians).toFloat()

                val x2 =
                    center.x + (radius + strokeWidth / 2 + lineLength1) * cos(angleInRadians).toFloat()
                val y2 =
                    center.y + (radius + strokeWidth / 2 + lineLength1) * sin(angleInRadians).toFloat()

                val isLeft = x2 < center.x
                val x3 = if (isLeft) x2 - lineLength2 else x2 + lineLength2
                val y3 = y2

                drawLine(
                    color = Color.LightGray,
                    start = Offset(x1, y1),
                    end = Offset(x2, y2),
                    strokeWidth = 2f,
                    alpha = animateAlpha
                )
                drawLine(
                    color = Color.LightGray,
                    start = Offset(x2, y2),
                    end = Offset(x3, y3),
                    strokeWidth = 2f,
                    alpha = animateAlpha
                )

                val infoText = if (isPercentageMode) {
                    val percentage = (pair.second / totalAmount) * 100
                    "${pair.first} ${String.format(Locale.getDefault(), "%.1f", percentage)}%"
                } else {
                    "${pair.first} ${String.format(Locale.getDefault(), "%.2f", pair.second)}"
                }

                val textLayoutResult = textMeasurer.measure(
                    text = infoText,
                    style = androidx.compose.ui.text.TextStyle(fontSize = 11.sp, color = color.copy(alpha = animateAlpha))
                )

                val textLeft =
                    if (isLeft) x3 - textLayoutResult.size.width - 4.dp.toPx() else x3 + 4.dp.toPx()
                drawText(
                    textLayoutResult = textLayoutResult,
                    topLeft = Offset(textLeft, y3 - textLayoutResult.size.height / 2f)
                )
            }

            startAngle += sweepAngle
        }

        // Draw center text
        if (animateAlpha > 0f) {
            val titleLayoutResult =
                textMeasurer.measure(text = centerTitle, style = centerTitleStyle.copy(color = centerTitleStyle.color.copy(alpha = animateAlpha)))
            val subtitleLayoutResult =
                textMeasurer.measure(text = centerSubtitle, style = centerSubtitleStyle.copy(color = centerSubtitleStyle.color.copy(alpha = animateAlpha)))

            val totalHeight =
                titleLayoutResult.size.height + subtitleLayoutResult.size.height + 4.dp.toPx()

            drawText(
                textLayoutResult = titleLayoutResult,
                topLeft = Offset(
                    center.x - titleLayoutResult.size.width / 2f,
                    center.y - totalHeight / 2f
                )
            )
            drawText(
                textLayoutResult = subtitleLayoutResult,
                topLeft = Offset(
                    center.x - subtitleLayoutResult.size.width / 2f,
                    center.y - totalHeight / 2f + titleLayoutResult.size.height + 4.dp.toPx()
                )
            )
        }
    }
}
